// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.36;
type Wad is uint256;
contract Base {
    struct Pair { uint256 first; uint256 second; }
    enum Mode { Off, On }
    event Changed(address indexed who, uint256 value);
    error Bad(uint256 value);
    uint256 public value;
    function bump(uint256 x) public virtual returns (uint256 y) {
        y = x + 1;
        value = y;
        emit Changed(msg.sender, y);
    }
}
contract Derived is Base {
    function bump(uint256 x) public override returns (uint256) {
        if (x == 0) revert Bad(x);
        return super.bump(x);
    }
}
